pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor (sender) and amount (msg.value) and unlockTime
    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        // keep amount in a reasonable range and non-zero to exercise balances
        amount = bound(amount, 0, 5 ether);
        vm.assume(actor != address(0));

        // ensure actor has funds to send
        vm.deal(actor, amount + 1 ether);

        // perform an initial Put to possibly create a non-zero prior balance
        uint256 initial = amount / 2; // derived from fuzzed amount so not constant across runs
        if (initial > 0) {
            vm.prank(actor);
            c.Put{value: initial}(unlockTime);
        }

        // Now perform the decisive Put with the fuzzed amount
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Read the stored balance and the last logged message value from the Log contract
        // Acc is public mapping: Acc(actor).balance accessible as c.Acc(actor) returns (uint unlockTime, uint balance)
        (uint storedUnlock, uint storedBalance) = c.Acc(actor);
        // LogFile is public variable of type Log. Its History is public array of Message structs, Message has fields (Sender, Data, Val, Time)
        // We read the last History entry via LogFile().History(lastIndex)
        // First get length via History length public getter: c.LogFile().History(uint) doesn't exist directly; but Log contract History is public, generating History(uint)-> (Sender, Data, Val, Time).
        // The Log contract instance is accessible via the public variable LogFile() getter which returns address of Log? Actually in original C, LogFile is declared as `Log LogFile;` with no public, so no getter. But LogFile is not public — however Log contract's History is public, so we must access Log via address provided at construction. In setUp we passed address(this) as log, so our test contract acts as the Log contract. We'll expose a LastMsgVal getter by implementing the same AddMessage in this test contract (we are the log) and a public History getter is not needed because C will call into this contract's AddMessage which will record LastMsgVal.

        // Because we deployed c with address(this) as Log, our test contract must have recorded the last message's Val. We stored it in lastLoggedVal.
        uint256 lastLoggedVal = lastLoggedValLocal;

        // The universal property: after Put completes, the logged Val equals the stored balance for that actor.
        assertTrue(lastLoggedVal == storedBalance);
    }

    // Implement minimal Log contract interface so C can call AddMessage on address(this)
    struct MessageLocal {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    MessageLocal[] public HistoryLocal;
    MessageLocal public LastMsgLocal;
    uint256 public lastLoggedValLocal;

    // This function matches Log.AddMessage signature used by C
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsgLocal.Sender = _adr;
        LastMsgLocal.Time = block.timestamp;
        LastMsgLocal.Val = _val;
        LastMsgLocal.Data = _data;
        HistoryLocal.push(LastMsgLocal);
        lastLoggedValLocal = _val;
    }
}

