pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor (who calls) and two amounts: first deposit and second deposit
    function testFuzz_property(address actor, uint256 firstAmt, uint256 secondAmt) public {
        // Keep amounts in reasonable ranges and non-zero where needed
        firstAmt = bound(firstAmt, 0, 10 ether);
        secondAmt = bound(secondAmt, 1, 10 ether); // second deposit must be >0 to observe msg.value logged

        // We need prior balance > 0 to distinguish mutant behavior; allow firstAmt==0 as admissible but
        // then property still holds vacuously; to ensure the domain includes cases that trigger mutant,
        // we do not assume firstAmt>0 here — fuzzer will try many combos.

        // Fund actor so they can send ETH
        vm.deal(actor, firstAmt + secondAmt + 1 ether);

        // Perform first deposit (maybe zero)
        vm.startPrank(actor);
        c.Put{value: firstAmt}(0);
        vm.stopPrank();

        // Now perform second deposit which will be logged as msg.value (secondAmt)
        vm.startPrank(actor);
        c.Put{value: secondAmt}(0);
        vm.stopPrank();

        // Read contract-observable values: the Log contract is at address passed in constructor (this)
        // The Log in reference records LastMsg.Val as the newest pushed value. The Log contract has public History array,
        // but we cannot import Log type. However, address(this) is the Log contract (we passed it), and we can
        // read its storage via public getter: History(uint) is auto-generated in Log; index of last message is len-1.
        // We can read Acc[actor].balance via c.Acc(actor).

        // Compute index of last log: call History length via low-level call to this contract's public History(uint) getter is available here.
        // Since this test contract implements Log (as not), but we can call the auto getter on this test contract because Log is separate.
        // Instead, simply assert the invariant using c.Acc(actor).balance and reading the last Log History entry via the Log ABI

        // Use Log interface to read History on this (we deployed C with Log = address(this)), so this contract must expose the same getter.
        // But this test contract doesn't implement Log; however the Log contract in source expects to be at address(this) in deployment of C.
        // To access the History entry, we perform a low-level staticcall to address(this) using the known selector for History(uint256).

        // Prepare selector for History(uint256) -> returns (address,string,uint,uint)
        bytes memory payload = abi.encodeWithSignature("History(uint256)", uint256(0));
        // First we need the length of History. The Log contract has public array History, so there's an auto getter History(uint) returning tuple,
        // but no direct length getter. However the Log contract also exposes History public array, and reading an index that is out of bounds will revert.
        // To find last index, we can binary search length by probing increasing indices until a call reverts — but vm calls to this test contract will not revert.
        // Simpler approach: The LastMsg is a public struct? In Log the LastMsg is not public. But History.push(LastMsg) so the last pushed index equals (number of pushes -1).
        // Since we control this test contract as Log (we passed address(this) when deploying c), and our contract DOES NOT implement AddMessage,
        // the actual Log used at runtime is the Log contract from the source, not this test contract. That Log's History getter is available at address(this).
        // We can fetch the last pushed message by trying successive indices from a reasonable upper bound downward. Keep bound wide but small cost.

        // Probe for last index by expanding until a call reverts; to avoid heavy loops in fuzz, limit attempts to 50.
        int lastIndex = -1;
        for (uint256 i = 0; i < 50; i++) {
            // try call index i
            (bool ok, ) = address(this).staticcall(abi.encodeWithSignature("History(uint256)", i));
            if (!ok) {
                // first failing index means length == i
                lastIndex = int(i) - 1;
                break;
            }
        }
        if (lastIndex == -1) {
            // if none failed within 50, assume length is 50 or more; set lastIndex to 49
            lastIndex = 49;
        }

        // Read History(lastIndex) tuple
        (bool ok2, bytes memory ret) = address(this).staticcall(abi.encodeWithSignature("History(uint256)", uint256(lastIndex)));
        // If this call fails, set ok2 false; in that case the test cannot proceed — but reference guarantees pushes so should succeed
        require(ok2, "reading History failed");

        // Decode (address,string,uint256,uint256)
        (address senderLogged, string memory dataLogged, uint256 valLogged, uint256 timeLogged) = abi.decode(ret, (address, string, uint256, uint256));

        // Read stored balance for actor
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(actor);

        // The general property we assert: for the reference contract, when the second Put happens with msg.value == valLogged,
        // and the last log entry corresponds to that second Put (sender matches actor and Data == "Put"), then the logged Val equals the stored balance.
        // This will hold in reference for all inputs; the mutant which logs before updating balance can cause valLogged != storedBalance when prior balance>0.

        bool predicate = (senderLogged == actor) && (keccak256(bytes(dataLogged)) == keccak256(bytes("Put"))) && (valLogged == storedBalance);
        assertTrue(predicate);
    }
}

