pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: two deposit amounts and two unlock times, and the actor
    function testFuzz_property(address actor, uint256 a1, uint256 a2, uint256 t1, uint256 t2) public {
        // Keep actor non-zero
        vm.assume(actor != address(0));
        // Bound amounts to reasonable values so they are >= MinSum (1 ether) or may be smaller; keep wide
        a1 = bound(a1, 0, 10 ether);
        a2 = bound(a2, 0, 10 ether);
        // Ensure we have some chance of prior non-zero balance by allowing a1>0
        // but do NOT require it (the property must hold for all admissible inputs)

        // Provide actor with funds to send
        vm.deal(actor, a1 + a2 + 1 ether);

        // First deposit: actor calls Put with a1 and t1
        vm.prank(actor);
        c.Put{value: a1}(t1);

        // Second deposit: actor calls Put with a2 and t2
        vm.prank(actor);
        c.Put{value: a2}(t2);

        // Now inspect: for the reference, the Log's last message Val equals the holder's stored balance for actor
        // Accessing public mappings: Acc(actor) returns (unlockTime, balance) via autogenerated getter
        (, uint256 storedBalance) = c.Acc(actor);

        // The Log contract is passed as address(this) in setUp; its History public array gives last entry
        // The reference's behavior: after the second Put completes, the last logged Val == storedBalance
        // Query the last History entry's Val via the Log public getter. History is public array of Message
        // Message layout: Sender, Data, Val, Time — so History(i) returns (address,string,uint,uint)

        uint256 historyLen = c.LogFile().HistoryLength();

        // The C contract given in problem has LogFile public but not a helper to get length; we must instead
        // call History(uint) with index; but we don't know length. Instead, the Log contract in original exposes
        // History public array; to read last entry we can try indices downward until success — but that's not allowed.
        // Simpler: The Log contract also stores LastMsg and pushes it; the autogenerated getter for LastMsg doesn't exist
        // So we MUST observe via the public History array. The returned History length is accessible by calling
        // c.LogFile().History(uint256) with index; but we need the last index. Fortunately, the Log contract's History
        // public array creates a getter History(uint) -> (address,string,uint,uint). We can read index 0 when only one entry,
        // but here we know exactly two Put calls were made, so the last index is 1 (zero-based) if both calls produced logs.
        // Both Put calls in reference and mutant call LogFile.AddMessage, so there will be at least 2 entries.

        // So we read History index 1 (the second entry) which corresponds to the second Put's log
        (address loggedSender, string memory, uint256 loggedVal, uint256) = c.LogFile().History(1);

        // The universal property: for ALL fuzz inputs (within our bounds and actor != 0), the reference satisfies
        // loggedVal == storedBalance. The mutant (which logs msg.value before updating balance) will have loggedVal == a2
        // while storedBalance == a1 + a2 for a1 > 0, causing inequality.

        // One assertion reading c's public surface
        assertTrue(loggedSender == actor && loggedVal == storedBalance);
    }
}

